"""Four rotating full-text section reviews with inspected citation leads."""
import json,xml.etree.ElementTree as E
import ledger as L
from review_batch_0001 import evidence
ROWS=[
('10.3390/nano5010180','PMC5312861','background_or_review','review','Abstract,Introduction,origami-related array discussion,Conclusions and refs11/84','Review of DNA-stabilized silver clusters. Origami is a cited scaffold prospect and nanoparticle-array precedent; inspected discussion does not establish a newly constructed origami design. Distinguish short DNA cluster ligands and proposed multi-cluster arrays from verified origami source sets. Remaining sections and complete bibliography require review.',[('B11-nanomaterials-05-00180','10.1038/nature04586'),('B84-nanomaterials-05-00180','10.1021/nl202066c')]),
('10.3389/fimmu.2015.00323','PMC4473697','background_or_review','review','Abstract,origami discussion in Bioinformatics Approaches,Challenges section and ref18','Review/perspective on nanotechnology and synthetic biology for leishmaniasis. Discusses origami generically among DNA nanotechnology approaches; challenges section frames future nanomaterials/informatics work. No concrete origami design/source set established in inspected sections. Ref18 is a one-dimensional DNA nanotechnology review, not proof of an experimentally built origami.',[('B18','10.1016/j.copbio.2013.02.005')]),
('10.1371/journal.pone.0132132','PMC4489926','not_origami','journal_article','Abstract,Introduction,model/results paragraphs,Materials and Methods,Conclusions and refs36–39','Study models DNA as500bead chains with terminal and internal adhesive pairs. L-DNA/S-DNA differ in persistence length;20nonredundant sticky-pair placements are simulation configurations, not origami designs. Methods use Kremer-Grest/FENE/excluded-volume and sticky potentials. Origami occurs as background precedent for selective sequence bonding. Same-agent exclusion audit rechecked model and methods; no simulations run. Supporting numerical results remain uninspected.',[('pone.0132132.ref036','10.1002/(sici)1521-3773(19981217)37:23<3220::aid-anie3220>3.0.co;2-c'),('pone.0132132.ref037','10.1038/nature01406'),('pone.0132132.ref038','10.1038/nmeth.1570'),('pone.0132132.ref039','10.1002/anie.201105846')]),
('10.1186/s11671-015-1102-1','PMC4609306','not_origami','journal_article','Abstract,Background,Methods fabrication paragraphs,Conclusions and refs24/25','Quasi3D plasmonic oligomers are fabricated by four-step silver deposition using a polystyrene-sphere monolayer mask on BK7 glass. DNA origami is a cited alternative fabrication approach, not the scaffold used in this experiment. Same-agent exclusion audit rechecked fabrication methods and conclusion. Left/right chirality and sphere/deposition settings do not establish DNA designs. Citation targets retained for discovery.',[('CR24','10.1021/ja404354c'),('CR25','10.1021/nl400538y')])]
def main():
 pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 for key,pmc,rel,typ,loc,note,refs in ROWS:
  path=L.ROOT/'assets/sources/pre2020-expansion'/(pmc+'.xml');ev=evidence(path,'https://pmc.ncbi.nlm.nih.gov/articles/'+pmc+'/',loc);p=pubs[key]
  if ev not in p['evidence']:p['evidence'].append(ev)
  p.update(title=p['legacy_record']['publication'],publication_type=[typ],review_stage='fulltext_reviewed',relevance=rel,design_contributions=[],catalog_eligibility='excluded' if rel=='not_origami' else 'unresolved',access='available',rationale=note,unresolved_questions=['Finish uninspected text/supporting material and full bibliography as applicable.','Follow cited origami leads and forward/author discovery routes.'],reviewer='Codex named primary XML sections; same-agent method-based exclusion audit',run_id='B0015',date=L.DATE)
  L.upsert('publication_reviews',p,'Record rotating full-text section review and construct-based relevance')
  root=E.parse(path)
  for rid,target in refs:
   assert root.find('.//ref[@id="'+rid+'"]') is not None
   L.upsert('discovery_edges',dict(edge_id='B0015:'+pmc+':'+rid,source_key=key,target_key=target,relation='cites',evidence_url=ev['url'],local_file=ev['local_file'],sha256=ev['sha256'],locator='Reference '+rid,reconciliation_state='pending',run_id='B0015',date=L.DATE),'Preserve inspected bibliography lead without automatic target classification')
 b=next(b for b in L.read('batches') if b['batch_id']=='B0015');b['completed_actions'].append('Four rotating XML reviews saved: two background reviews,two methods-audited nonorigami exclusions;20of25 first passes.')
 b.update(after_counts=L.counts(),validation=[L.validate()],next_queue=['JoVE52486;G-quadruplex chapter;AJB biotin-streptavidin;epmc1835 thesis;drug-delivery review','FNANO2010,234CV identities and previous source/citation followups'])
 L.upsert('batches',b,'Save20of25 first-pass coverage')
 L.atomic(L.HERE/'batch_0015_rotation_second_audit.json',json.dumps(dict(reviewed_keys=[r[0] for r in ROWS],first_pass_count=20,input_count=25,exclusion_audit='Same-agent comparison of actual model/fabrication methods to background origami citations for both exclusions',validation=L.validate(),counts=L.counts()),indent=2)+'\n');print(L.validate())
if __name__=='__main__':main()
